{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "The Critical Failure of Dying",
      "goal": "Introduce Arthur and his accidental 'Glass Cannon' Isekai transition where every hit he lands is a crit, but he has exactly 1 HP.",
      "chapter_role": "hook",
      "stakes_shift": "From mundane debt-ridden life to a high-stakes survival game where a stubbed toe means permadeath.",
      "bridge": {
        "from_prev": "Arthur's final moments in the real world during a freak electrical accident.",
        "to_next": "Arthur stands at the entrance of the 'Newbie Slums' with a glowing red warning over his head."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 2,
      "title": "Tutorials are for People with HP",
      "goal": "Arthur must clear the basic combat tutorial without taking a single point of environmental or monster damage.",
      "chapter_role": "setup",
      "stakes_shift": "Arthur realizes he can't play the game normally and must find 'exploits' in movement and stealth to survive.",
      "bridge": {
        "from_prev": "Arthur enters the tutorial zone with his 1 HP handicap.",
        "to_next": "Arthur discovers a hidden vendor who sells items that shouldn't be available to level 1s."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "Exploiting the Economy",
      "goal": "Arthur uses his 100% crit rate to 'farm' high-level materials from passive mobs that usually require high-level parties.",
      "chapter_role": "investigation",
      "stakes_shift": "Arthur goes from a penniless 'glitch' to a wealthy outlier, attracting the attention of a local merchant guild.",
      "bridge": {
        "from_prev": "Arthur secures his first 'overkill' drop from a Crystal Tortoise.",
        "to_next": "A guild representative offers Arthur a 'deal' that smells like a trap."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 4,
      "title": "Dungeon Diving on a Budget",
      "goal": "To avoid the guild's pressure, Arthur dives into a 'Death-Touch' dungeon where everything dies in one hit—including him.",
      "chapter_role": "pressure",
      "stakes_shift": "The environment itself becomes the enemy, shifting the focus from combat to precision platforming.",
      "bridge": {
        "from_prev": "Arthur enters the 'Shatter-Glass Crypt' to hide from guild enforcers.",
        "to_next": "Arthur accidentally triggers a party-requirement boss while solo."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 5,
      "title": "Worst Party Member Ever",
      "goal": "Arthur is forced to team up with a naive Paladin who insists on 'protecting' him, which actually makes his stealth-based survival impossible.",
      "chapter_role": "alliance",
      "stakes_shift": "Arthur must manage another person's AI/behavior to keep himself from being collateral damage.",
      "bridge": {
        "from_prev": "The Paladin 'rescues' Arthur from a shadow, nearly crushing him with a heavy shield.",
        "to_next": "The duo reaches the final chamber where a boss with an 'Aura of Thorns' resides."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "The Reflect Damage Problem",
      "goal": "Arthur faces a boss that reflects 1% of damage taken—a death sentence for a 1 HP crit-machine.",
      "chapter_role": "confrontation",
      "stakes_shift": "Arthur has to find a way to deal damage without 'hitting' the boss or find a loophole in the System's math.",
      "bridge": {
        "from_prev": "The boss activates its Reflective Shell, halting Arthur's offense.",
        "to_next": "The boss falls to a mathematical technicality, but the System triggers a 'Balance Patch' alert."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 7,
      "title": "Hit, Run, and Repeat",
      "goal": "Arthur must escape the dungeon before the System 'patches' his existence out of the world.",
      "chapter_role": "climax",
      "stakes_shift": "Survival is no longer just about HP; it's about staying ahead of the System's administration.",
      "bridge": {
        "from_prev": "The world begins to pixelate as the 'Balance Patch' initiates.",
        "to_next": "Arthur escapes into a 'Legacy Zone' where the patch can't reach him, ready for the next exploit."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    }
  ]
}

